const normalizeHandle=h=>String(h||'').trim().replace(/^@/,'').toLowerCase();
function octoberSchedule(members=[]){const find=h=>{const matches=members.filter(m=>normalizeHandle(m.handle)===normalizeHandle(h));return matches.length===1?matches[0]:null;};const occurrences={};const rows=[...Object.entries(OCTOBER_GROUPS).sort(([a],[b])=>a.localeCompare(b)).map(([d,handles])=>({date:'2026-10-'+d,handles,title:'Club carousel · '+d+' October',type:'Basic Club Carousel'})),...OCTOBER_SOLOS.map(([d,h])=>{const occurrence=occurrences[h]=(occurrences[h]||0)+1,m=find(h);return {date:'2026-10-'+d,handles:[h],title:'@'+h+' · Premium feature',type:m?.tier==='Premium+'?'Premium+ Feature '+Math.min(occurrence,2):'Premium Solo'};})];return rows.map((r,i)=>({...r,id:'c6102026-0000-4000-8000-'+String(i+1).padStart(12,'0'),import_key:'owner-october-2026-'+(i+1),member_ids:r.handles.map(find).filter(Boolean).map(m=>String(m.id)),scheduled_handles:r.handles.map(h=>'@'+h),status:'Scheduled',content_ready:false,caption_ready:false,notes:'From your supplied October 2026 schedule. Publication and content readiness have not been confirmed.'}));}
async function importOctoberSchedule(store){if(store.list('migration').some(r=>r.source==='owner-october-2026'))return 0;const existing=store.list('content');let added=0;for(const row of octoberSchedule(store.members)){if(existing.some(p=>p.id===row.id||p.import_key===row.import_key))continue;const same=existing.find(p=>p.date===row.date&&p.type===row.type&&((p.scheduled_handles||[]).map(normalizeHandle).sort().join('|')===row.handles.map(normalizeHandle).sort().join('|')||(p.member_ids?.length===row.handles.length&&[...p.member_ids].sort().join('|')===[...row.member_ids].sort().join('|'))));if(same){await store.save('content',{...same,import_key:row.import_key,scheduled_handles:row.scheduled_handles},same.id);continue;}const {id,handles,...data}=row;await store.save('content',data,id);added++;}await store.save('migration',{source:'owner-october-2026',imported_at:new Date().toISOString(),posts:33},'c6102026-0000-4000-8001-000000000001');return added;}

const TIERS={ 'Basic (Legacy)':{price:3.50,solo:0,carousel:1},Basic:{price:5.99,solo:0,carousel:1},Premium:{price:9.99,solo:1,carousel:1},'Premium+':{price:19.99,solo:2,carousel:1}};
const TYPES=['Basic Club Carousel','Premium Solo','Premium+ Feature 1','Premium+ Feature 2','Editorial','Non-member Feature','Sponsor','Contest','Reel','Other'];
const STATUSES=['Draft','Waiting for content','Ready','Scheduled','Published','Skipped'];
const ROUNDS=['Entries','R128','R64','R32','Top 16','Quarter-final','Semi-final','Final','Winner'];
const DEFAULT_POINTS={'Entries':1,'R128':2,'R64':3,'R32':5,'Top 16':8,'Quarter-final':12,'Semi-final':18,'Final':25,'Winner':40};
const day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const month=(d=new Date())=>day(d).slice(0,7);
const active=m=>!['CANCELLED','EXPIRED','SUSPENDED','APPROVAL_PENDING','APPROVED','INACTIVE'].includes(m.paypal_status);
function tier(m){return m.tier==='Basic'&&(m.paypal_plan_id==='P-79Y21508MP396202VMTEPYHI'||(!m.paypal_plan_id&&(m.monthly_price==null||+m.monthly_price===3.5)))?'Basic (Legacy)':m.tier;}
const price=m=>Number.isFinite(Number(m.monthly_price))&&m.monthly_price!==null?+m.monthly_price:TIERS[tier(m)]?.price||0;
const mrr=ms=>ms.filter(active).reduce((n,m)=>n+price(m),0);
function entitlement(m,config=TIERS){const t=config[tier(m)]||{solo:0,carousel:0};return [...(t.carousel?['Basic Club Carousel']:[]),...Array.from({length:t.solo},(_,i)=>tier(m)==='Premium'?'Premium Solo':`Premium+ Feature ${i+1}`)];}
function fulfilment(m,items,mo,config=TIERS){const required=entitlement(m,config),linked=items.filter(p=>p.date?.startsWith(mo)&&p.member_ids?.includes(String(m.id))&&p.status!=='Skipped');let published=0,scheduled=0;const missing=[];for(const type of required){const p=linked.filter(p=>p.type===type);if(p.some(p=>p.status==='Published'))published++;else if(p.some(p=>['Ready','Scheduled'].includes(p.status)))scheduled++;else missing.push(type);}
return{promised:required.length,published,scheduled,outstanding:required.length-published,unscheduled:missing.length,missing,ratio:required.length?published/required.length:1,linked};}
function generate(ms,items,mo,config=TIERS,now=new Date()){
 const end=new Date(+mo.slice(0,4),+mo.slice(5,7),0).getDate();const start=mo===month(now)?now.getDate():1;if(mo<month(now))throw Error('Past months are history. Add corrections manually.');let cursor=0;const result=[];
 const date=()=>`${mo}-${String(Math.min(end,start+(cursor++%Math.max(1,end-start+1)))).padStart(2,'0')}`;
 const needs=ms.filter(active).map(m=>({m,types:entitlement(m,config).filter(type=>!items.some(p=>p.date?.startsWith(mo)&&p.status!=='Skipped'&&p.type===type&&p.member_ids?.includes(String(m.id))))}));
 const basic=needs.filter(n=>n.types.includes('Basic Club Carousel'));for(let i=0;i<basic.length;i+=10)result.push({title:`Club collective · ${Math.floor(i/10)+1}`,type:'Basic Club Carousel',date:date(),member_ids:basic.slice(i,i+10).map(n=>String(n.m.id)),status:'Draft',content_ready:false,caption_ready:false});
 for(const {m,types} of needs)for(const type of types.filter(t=>t!=='Basic Club Carousel'))result.push({title:m.handle||'Member feature',type,date:date(),member_ids:[String(m.id)],status:'Draft',content_ready:false,caption_ready:false});return result;
}
function totals(ms,items,mo,config=TIERS){return ms.filter(active).reduce((s,m)=>{const f=fulfilment(m,items,mo,config);for(const k of ['promised','published','scheduled','outstanding','unscheduled'])s[k]+=f[k];return s;},{promised:0,published:0,scheduled:0,outstanding:0,unscheduled:0});}
function leaderboard(contests,points=DEFAULT_POINTS){const rows=new Map();for(const c of contests)for(const e of c.entries||[]){const key=e.member_id||e.handle;if(!key)continue;const r=rows.get(key)||{id:key,handle:e.handle,member_id:e.member_id,entered:0,wins:0,podiums:0,points:0};r.entered++;r.points+=Number(points[e.result||'Entries']||0);r.wins+=e.result==='Winner'?1:0;r.podiums+=['Winner','Final','Semi-final'].includes(e.result)?1:0;rows.set(key,r);}return [...rows.values()].sort((a,b)=>b.points-a.points||b.wins-a.wins||String(a.handle).localeCompare(String(b.handle))).map((r,i)=>({...r,rank:i+1}));}
function scenario(ms,{basicPremium=0,basicPlus=0,newBasic=0,newPremium=0,cancellations=0}={}){const basics=ms.filter(m=>active(m)&&tier(m).startsWith('Basic'));const n=Math.min(basics.length,Math.max(0,basicPremium)),p=Math.min(basics.length-n,Math.max(0,basicPlus));const gain=basics.slice(0,n).reduce((s,m)=>s+9.99-price(m),0)+basics.slice(n,n+p).reduce((s,m)=>s+19.99-price(m),0);const current=mrr(ms),arpm=current/(ms.filter(active).length||1);const delta=gain+Math.max(0,newBasic)*5.99+Math.max(0,newPremium)*9.99-Math.min(ms.filter(active).length,Math.max(0,cancellations))*arpm;return{current,delta,projected:Math.max(0,current+delta),annual:delta*12};}
function safeURL(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function csv(rows){return rows.map(row=>row.map(x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}

// A deterministic daily rotation: every eligible handle gets a turn before repeating.
function dailyRound(members,date=day(),count=5){const pool=members.filter(m=>active(m)&&m.handle?.trim()).sort((a,b)=>String(a.id).localeCompare(String(b.id)));if(!pool.length)return[];const offset=((Math.floor(Date.parse(date+'T00:00:00Z')/86400000)*count)%pool.length+pool.length)%pool.length;return Array.from({length:Math.min(count,pool.length)},(_,i)=>pool[(offset+i)%pool.length]);}
function bracketRounds(entries,winners={}){let slots=Array.from({length:128},(_,i)=>entries[i]||null),rounds=[];for(let r=0;r<7;r++){const matches=[];for(let i=0;i<slots.length;i+=2){const pair=[slots[i],slots[i+1]],key=r+'-'+i/2,winner=pair.every(Boolean)?pair.find(e=>e.key===winners[key])||null:null;matches.push({key,pair,winner});}rounds.push(matches);slots=matches.map(m=>m.winner);}return rounds;}
function bracketWin(contest,key,entrant){const rounds=bracketRounds(contest.entries,contest.winners),[r,i]=key.split('-').map(Number),match=rounds[r]?.[i];if(!match||!match.pair.every(Boolean)||!match.pair.some(e=>e.key===entrant))throw Error('Both entrants must be decided first.');const winners={...contest.winners,[key]:entrant};for(let next=r+1,index=Math.floor(i/2);next<7;next++,index=Math.floor(index/2))delete winners[next+'-'+index];return winners;}
function careRound(members,checks,date=day(),count=5,priority=()=>0){const pool=dailyRound(members,date,members.length||1),offset=pool.length?Math.floor(Date.parse(date+'T00:00:00Z')/86400000)%pool.length:0;const rotated=pool.slice(offset).concat(pool.slice(0,offset));const recent=id=>checks.filter(c=>c.member_id===String(id)&&c.completed_at?.slice(0,10)<date).map(c=>c.completed_at).sort().at(-1)||'';return rotated.map((m,i)=>({m,i,last:recent(m.id),score:priority(m)})).sort((a,b)=>{const aRecent=a.last&&Date.parse(date)-Date.parse(a.last)<7*86400000,bRecent=b.last&&Date.parse(date)-Date.parse(b.last)<7*86400000;return Number(!!aRecent)-Number(!!bRecent)||b.score-a.score||a.last.localeCompare(b.last)||a.i-b.i;}).slice(0,count).map(x=>x.m);}

function dailyProgress(posts,repostMembers,reposts,careMembers,checks,sponsors,today=day()){
 const completedToday=value=>value&&day(new Date(value))===today;
 const publishing=posts.filter(p=>p.date&&p.date<=today&&p.status!=='Skipped'&&(p.date===today||p.status!=='Published'||completedToday(p.published_at)));
 const rounds=repostMembers.map(m=>({...m,done:reposts.some(r=>r.member_id===String(m.id)&&r.round_date===today)}));
 const care=careMembers.map(m=>({...m,done:checks.some(c=>c.member_id===String(m.id)&&c.completed_at?.slice(0,10)===today)}));
 const commitments=sponsors.filter(s=>s.due_date&&s.due_date<=today&&!['Completed','Lost'].includes(s.stage)&&(!s.task_completed_at||completedToday(s.task_completed_at)));
 return {posts:publishing,reposts:rounds,care,sponsors:commitments,total:publishing.length+rounds.length+care.length+commitments.length,done:publishing.filter(p=>p.status==='Published').length+rounds.filter(m=>m.done).length+care.filter(m=>m.done).length+commitments.filter(s=>s.task_completed_at).length};
}
// CLUB RANDOM SCHEDULER / membership fulfilment remains linked to the existing content types.
const CLUB_DEFAULT_SIZES={basic:10,premium:2,plus:2};
let clubPlanner=null,clubGroupSizes={...CLUB_DEFAULT_SIZES},clubSavedBoard=null;
function shuffleClubMembers(rows){
 const shuffled=[...rows];
 // Fisher–Yates: each eligible member has the same chance of every position.
 const index=max=>{
  if(typeof crypto!=='undefined'&&crypto.getRandomValues){
   const a=new Uint32Array(1),limit=Math.floor(4294967296/max)*max;
   do{crypto.getRandomValues(a)}while(a[0]>=limit);
   return a[0]%max;
  }
  return Math.floor(Math.random()*max);
 };
 for(let i=shuffled.length-1;i>0;i--){const j=index(i+1);[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}
 return shuffled;
}
function clubMemberLabel(m){return m.handle?.trim()?(m.handle.trim().startsWith('@')?m.handle.trim():'@'+m.handle.trim()):'Member #'+m.id;}
function clubContentType(p){if(!p.auto_group||(p.member_ids||[]).length<2)return p.type;return ({'Premium Solo':'Premium group feature','Premium+ Feature 1':'Premium+ group · Feature 1','Premium+ Feature 2':'Premium+ group · Feature 2'})[p.type]||p.type;}
function clubSnapshot(target){
 return JSON.stringify({roster:store.members.filter(active).map(m=>[String(m.id),tier(m),m.handle]).sort((a,b)=>a[0].localeCompare(b[0])),benefits:config(),posts:content().filter(p=>p.date?.startsWith(target)&&p.status!=='Skipped').map(p=>[p.id,p.type,p.date,p.status,p.member_ids||[],p.scheduled_handles||[]]).sort((a,b)=>String(a[0]).localeCompare(String(b[0])))});
}
function randomClubSchedule(ms,existing,target,sizes,cfg=TIERS,now=new Date()){
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(target)||target<month(now))throw Error('Choose this month or a future month.');
 for(const [key,size] of Object.entries(sizes))if(!Number.isSafeInteger(size)||size<1||size>250)throw Error('Choose 1–250 members for '+key+' groups.');
 const roster=ms.filter(active);
 const existingMemberHandles=new Map();for(const m of roster){const norm=normalizeHandle(m.handle);if(norm&&!existingMemberHandles.has(norm))existingMemberHandles.set(norm,String(m.id));}
 const assigned=(type)=>{
  const done=new Set();
  for(const p of existing){if(p.group_board_version!==2||!p.date?.startsWith(target)||p.status==='Skipped'||p.type!==type)continue;
   for(const id of p.member_ids||[])done.add(String(id));
   for(const h of p.scheduled_handles||[]){const id=existingMemberHandles.get(normalizeHandle(h));if(id)done.add(id);}
  }
  return done;
 };
 const missing=(type,eligible)=>{const done=assigned(type);return eligible.filter(m=>!done.has(String(m.id)));};
 const basics=missing('Basic Club Carousel',roster); // EVERY active tier: Basic, Basic Legacy, Premium, Premium+.
 const premiums=missing('Premium Solo',roster.filter(m=>tier(m)==='Premium'&&entitlement(m,cfg).includes('Premium Solo')));
 const plusMembers=roster.filter(m=>tier(m)==='Premium+');
 const plusTypes=['Premium+ Feature 1','Premium+ Feature 2'];
 const plusPools=plusTypes.map(type=>missing(type,plusMembers.filter(m=>entitlement(m,cfg).includes(type))));
 const buckets=[
  {key:'basic',name:'Basic collective',type:'Basic Club Carousel',size:sizes.basic,pool:basics},
  {key:'premium',name:'Premium features',type:'Premium Solo',size:sizes.premium,pool:premiums},
  ...plusTypes.map((type,i)=>({key:'plus'+(i+1),name:'Premium+ · Feature '+(i+1),type,size:sizes.plus,pool:plusPools[i]}))
 ];
 for(const b of buckets){b.groups=[];const shuffled=shuffleClubMembers(b.pool);for(let i=0;i<shuffled.length;i+=b.size)b.groups.push(shuffled.slice(i,i+b.size));}
 const end=new Date(+target.slice(0,4),+target.slice(5,7),0).getDate(),start=target===month(now)?now.getDate():1;
 const days=Array.from({length:Math.max(0,end-start+1)},(_,i)=>target+'-'+String(start+i).padStart(2,'0'));
 if(!days.length)throw Error('No dates available for this month.');
 const ordered=[];let round=0;
 while(buckets.some(b=>b.groups.length>round)){for(const b of buckets){const members=b.groups[round];if(members)ordered.push({bucket:b,members,groupNumber:round+1});}round++;}
 const items=ordered.map(({bucket:b,members,groupNumber},i)=>{
  const best=days[ordered.length===1?0:Math.round(i*(days.length-1)/(ordered.length-1))];
  return {title:b.name+' · Group '+groupNumber,type:b.type,date:best,member_ids:members.map(m=>String(m.id)),scheduled_handles:members.map(clubMemberLabel),status:'Scheduled',content_ready:false,caption_ready:false,auto_group:true,group_board_version:2,auto_group_tier:b.key,notes:'Randomized Club scheduler. Premium and Premium+ are also included in the Basic collective. Content and caption still need preparation.'};
 });
 return {items,buckets,summary:{active:roster.length,basic:basics.length,premium:premiums.length,plus1:plusPools[0].length,plus2:plusPools[1].length}};
}
// Every group is an actionable Canva/Instagram production card, not just a calendar label.
function clubHandles(p){return (p.scheduled_handles?.length?p.scheduled_handles:p.member_ids?.map(id=>clubMemberLabel(member(id)||{id}))||[]).map(h=>String(h||'').trim()).filter(Boolean);}
function clubCategory(p){return p.auto_group_tier==='basic'?'BASIC · ALL TIERS':p.auto_group_tier==='premium'?'PREMIUM ONLY':p.auto_group_tier==='plus1'?'PREMIUM+ · FEATURE 1':'PREMIUM+ · FEATURE 2';}
function clubCategoryOrder(key){return {basic:0,premium:1,plus1:2,plus2:3}[key]??4;}
function clubSortedPosts(items){return [...items].sort((a,b)=>clubCategoryOrder(a.auto_group_tier)-clubCategoryOrder(b.auto_group_tier)||a.date.localeCompare(b.date)||a.title.localeCompare(b.title));}
function clubPostCopy(p){return clubHandles(p).join('\n');}
function clubProductionSchedule(posts,target){
 const counts={};return `JUSTABARTH CLUB · ${moLabel(target).toUpperCase()}\nINSTAGRAM POST SCHEDULE\n\n`+clubSortedPosts(posts).map(p=>{const category=clubCategory(p),n=counts[category]=(counts[category]||0)+1;return `${fmt(p.date).toUpperCase()} · ${category} · GROUP ${String(n).padStart(2,'0')}\n${clubPostCopy(p)}`;}).join('\n\n')+ '\n';
}
function clubCanvaSheet(posts,target){const counts={};const rows=[['Date','Tier / feature','Group','Member count','Handles for Canva (one per line)','Handles one-line','Group title','Status']];for(const p of clubSortedPosts(posts)){const category=clubCategory(p),number=counts[category]=(counts[category]||0)+1,handles=clubHandles(p);rows.push([p.date,category,'Group '+String(number).padStart(2,'0'),handles.length,handles.join('\n'),handles.join(' '),p.title,p.status]);}return csv(rows);}
async function clubCopy(text){
 if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard — paste into Canva or Instagram.');return;}catch{}}
 const el=document.createElement('textarea');el.value=text;el.setAttribute('readonly','');el.style.cssText='position:fixed;opacity:0;left:-9999px;top:0';document.body.append(el);el.select();const worked=document.execCommand?.('copy');el.remove();if(worked){toast('Copied — paste into Canva or Instagram.');return;}
 // Last-resort: expose editable, selectable text rather than claiming a successful copy.
 modal('Copy handles',`<textarea class="input" rows="12" readonly style="min-height:240px">${esc(text)}</textarea><p class="hint">Select all and copy this text to Canva.</p>`);
}
function clubGroupCards(posts,src){
 const counts={};return `<div class="club-groups">${clubSortedPosts(posts).map((p,i)=>{const group=clubCategory(p),groupIndex=counts[group]=(counts[group]||0)+1;
 return `<article class="club-group-card"><div class="club-group-top"><strong>${esc(group)} · GROUP ${String(groupIndex).padStart(2,'0')}</strong><time>${esc(fmt(p.date))}</time></div><div class="club-group-handles">${clubHandles(p).map(h=>`<span>${esc(h)}</span>`).join('')}</div><small>${clubHandles(p).length} handles · ${esc(clubContentType(p))}</small><div class="club-card-actions"><span class="club-copy-hint">One handle per line · ready to paste into Canva</span>${btn('⧉ Copy ALL @handles','club-copy-one','primary',`data-source="${src}" data-index="${i}" aria-label="Copy all handles from ${esc(group)} group ${groupIndex} for Canva"`)}</div></article>`;}).join('')}</div>`;
}
function clubProductionActions(source,posts){return `<div class="club-production-actions">${btn('Copy entire IG posting schedule','club-copy-ig','primary',`data-source="${source}"`)}${btn('Download Canva CSV','club-export-canva','quiet',`data-source="${source}"`)}${btn('Download printable handle list','club-export-text','quiet',`data-source="${source}"`)}</div>`;}
function clubSchedulePreview(result){
 const summary=result.summary;
 return `<div class="club-plan-summary"><div><strong>${summary.active}</strong><span>Active members</span></div><div><strong>${result.items.length}</strong><span>Posts to create</span></div><div><strong>${summary.basic}</strong><span>Basic inclusions</span></div><div><strong>${summary.premium}</strong><span>Premium features</span></div><div><strong>${summary.plus1+summary.plus2}</strong><span>Premium+ features</span></div></div>`+
 (summary.missingHandles?`<div class="note error">${summary.missingHandles} active member(s) have no Instagram handle saved. They will appear as Member #ID until you update their profile.</div>`:'')+
 (result.items.length?clubProductionActions('planned',result.items)+clubGroupCards(result.items,'planned'):'<div class="note success">Every eligible member benefit already has a planned post for this month. Open the Saved group board to view existing groups.</div>');
}
